// Minimal argparse clone replicating:
//   parser = argparse.ArgumentParser(prog='test9.mjs')
//   parser.add_argument('--a', type=str, required=True)
// Supports: --a value, --a=value, unambiguous-prefix abbreviation
// (--h/--he/... -> --help, --a is the only --a* option), -h/--help,
// argparse-style errors to stderr with exit code 2.

const PROG = 'test9.mjs';
const USAGE = `usage: ${PROG} [-h] --a A\n`;
const HELP =
  USAGE +
  '\n' +
  'options:\n' +
  '  -h, --help  show this help message and exit\n' +
  '  --a A\n';

const LONG_OPTIONS = ['--help', '--a'];

function errorExit(message) {
  process.stderr.write(USAGE);
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

function printHelpExit() {
  process.stdout.write(HELP);
  process.exit(0);
}

// Mirrors argparse's _negative_number_matcher: ^-\d+$|^-\d*\.\d+$
function isNegativeNumber(s) {
  if (s.length < 2 || s[0] !== '-') return false;
  let dotSeen = false;
  let digitsAfter = 0;
  for (let i = 1; i < s.length; i++) {
    const ch = s[i];
    if (ch >= '0' && ch <= '9') {
      if (dotSeen) digitsAfter++;
    } else if (ch === '.' && !dotSeen) {
      dotSeen = true;
    } else {
      return false;
    }
  }
  if (!dotSeen) return true; // '-' followed by one or more digits
  return digitsAfter >= 1;
}

// Mirrors argparse's _parse_optional returning None (i.e. the token is a
// positional/value rather than an option string).
function looksLikeOption(token) {
  if (token.length === 0) return false;
  if (token[0] !== '-') return false;
  if (token === '-') return false;
  if (isNegativeNumber(token)) return false;
  if (token.indexOf(' ') !== -1) return false;
  return true;
}

// Resolve a long option name (possibly abbreviated) to its full form.
// Returns the full option string, or null if there is no match.
function resolveLongOption(name) {
  if (LONG_OPTIONS.indexOf(name) !== -1) return name;
  const matches = [];
  for (const opt of LONG_OPTIONS) {
    if (opt.startsWith(name)) matches.push(opt);
  }
  if (matches.length === 1) return matches[0];
  if (matches.length > 1) {
    errorExit(`ambiguous option: ${name} could match ${matches.join(', ')}`);
  }
  return null;
}

export function parseArgs(argv) {
  let a;
  const extras = [];
  let i = 0;

  while (i < argv.length) {
    const token = argv[i];

    if (token.startsWith('--') && token.length > 2) {
      // Long option, possibly abbreviated, possibly with =value.
      let name = token;
      let explicitValue = null;
      const eq = token.indexOf('=');
      if (eq !== -1) {
        name = token.slice(0, eq);
        explicitValue = token.slice(eq + 1);
      }
      const resolved = resolveLongOption(name);
      if (resolved === null) {
        extras.push(token);
        i++;
        continue;
      }
      if (resolved === '--help') {
        if (explicitValue !== null) {
          errorExit(`argument -h/--help: ignored explicit argument '${explicitValue}'`);
        }
        printHelpExit();
      }
      // resolved === '--a'
      if (explicitValue !== null) {
        a = explicitValue;
        i++;
        continue;
      }
      const next = argv[i + 1];
      if (next === undefined || looksLikeOption(next)) {
        errorExit('argument --a: expected one argument');
      }
      a = next;
      i += 2;
      continue;
    }

    if (token === '-h') {
      printHelpExit();
    }

    // Anything else (unknown short options, '--', positionals) is an extra.
    extras.push(token);
    i++;
  }

  // argparse reports missing required arguments before unrecognized ones.
  if (a === undefined) {
    errorExit('the following arguments are required: --a');
  }
  if (extras.length > 0) {
    errorExit(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return { a };
}

