// Node.js ESM port of test9.py:
//   result = yaml.dump(yaml.safe_load(args.a), explicit_start=True)
//   print(result)

import { parseArgs } from './cli/args.mjs';
import { safeLoad } from './yaml/parser.mjs';
import { dumpDocument } from './yaml/dump.mjs';

const args = parseArgs(process.argv.slice(2));

let result;
try {
  result = dumpDocument(safeLoad(args.a));
} catch (err) {
  // Python lets the PyYAML exception propagate (traceback to stderr, exit 1).
  // We emit the error message to stderr and exit with the same status.
  const message = err && err.message ? err.message : String(err);
  process.stderr.write(message + '\n');
  process.exit(1);
}

// dumpDocument already ends with '\n'; print() adds one more.
process.stdout.write(result + '\n');

