mkdir -p /tmp/t9/cli /tmp/t9/yaml && cp /output/cli/args.mjs /tmp/t9/cli/ && cp /output/test9.mjs /tmp/t9/ && cat > /tmp/t9/yaml/parser.mjs <<'EOF'
export function safeLoad(s) {
  if (s === 'ERR') { const e = new Error('while parsing a flow mapping\n  boom'); e.name = 'ParserError'; throw e; }
  if (s === '' || s === 'null' || s === '~') return null;
  return { echoed: s };
}
EOF
cat > /tmp/t9/yaml/dump.mjs <<'EOF'
export function dumpDocument(v) {
  if (v === null) return '--- null\n...\n';
  return '---\nechoed: ' + JSON.stringify(v.echoed) + '\n';
}
EOF
echo done

