// Dependency-free YAML subset parser (safe_load equivalent).
// Pure ESM, no RegExp, no JSON. Char-by-char scanners throughout.
//
// export function safeLoad(text) -> JS value
//   null / bool / number / string / Array / plain object (insertion order).
// Plain scalars are resolved through resolveScalar() from './resolve.mjs'.

import { resolveScalar } from './resolve.mjs';

// ---------------------------------------------------------------------------
// small char helpers (no regex anywhere)

function isSpaceTab(ch) {
  return ch === ' ' || ch === '\t';
}

function isFlowIndicator(ch) {
  return ch === ',' || ch === '[' || ch === ']' || ch === '{' || ch === '}';
}

function rtrim(s) {
  let end = s.length;
  while (end > 0 && isSpaceTab(s[end - 1])) end--;
  return s.slice(0, end);
}

function indentOf(line) {
  let i = 0;
  while (i < line.length && line[i] === ' ') i++;
  return i;
}

function isBlank(line) {
  for (let i = 0; i < line.length; i++) {
    if (!isSpaceTab(line[i])) return false;
  }
  return true;
}

function isComment(line) {
  let i = 0;
  while (i < line.length && isSpaceTab(line[i])) i++;
  return line[i] === '#';
}

// '---' / '...' marker at column 0, followed by EOL or separation space.
function isDocMarker(line, marker) {
  if (line.length < 3) return false;
  if (line[0] !== marker[0] || line[1] !== marker[1] || line[2] !== marker[2]) {
    return false;
  }
  return line.length === 3 || isSpaceTab(line[3]);
}

function isSeqEntry(content) {
  return content[0] === '-' && (content.length === 1 || isSpaceTab(content[1]));
}

// Split text into lines on \n, \r\n, \r, NEL, LS, PS. Reports whether the
// input ended with a line break (matters for block scalar chomping).
function splitLines(text) {
  const lines = [];
  let cur = '';
  let endedWithBreak = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === '\r') {
      if (text[i + 1] === '\n') i++;
      lines.push(cur);
      cur = '';
      endedWithBreak = true;
    } else if (ch === '\n' || ch === '' || ch === ' ' || ch === ' ') {
      lines.push(cur);
      cur = '';
      endedWithBreak = true;
    } else {
      cur += ch;
      endedWithBreak = false;
    }
  }
  if (!endedWithBreak && cur !== '') lines.push(cur);
  return { lines, endedWithBreak };
}

// Cut a plain-scalar segment at a ' #' comment start, then right-trim.
function cutComment(s) {
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '#' && (i === 0 || isSpaceTab(s[i - 1]))) {
      return rtrim(s.slice(0, i));
    }
  }
  return rtrim(s);
}

function toKeyString(v) {
  if (v === null) return 'null';
  if (v === true) return 'true';
  if (v === false) return 'false';
  if (typeof v === 'number') return String(v);
  return v;
}

// Folded-style joining of block-scalar body rows ('' = empty row).
// A break folds to a space only between two non-empty, non-more-indented
// rows; a break before an empty row is dropped (the empty row itself emits
// the newline); breaks adjacent to more-indented rows are preserved.
function foldRows(rows) {
  let out = '';
  for (let i = 0; i < rows.length; i++) {
    if (i > 0) {
      const a = rows[i - 1];
      const b = rows[i];
      const moreA = a.length > 0 && isSpaceTab(a[0]);
      const moreB = b.length > 0 && isSpaceTab(b[0]);
      if (a === '') out += '\n';
      else if (b === '') { if (moreA) out += '\n'; }
      else if (moreA || moreB) out += '\n';
      else out += ' ';
    }
    out += rows[i];
  }
  return out;
}

// Double-quoted escape table.
const DQ_ESCAPES = {
  '0': '\0', a: '\x07', b: '\b', t: '\t', n: '\n', v: '\x0b',
  f: '\f', r: '\r', e: '\x1b', ' ': ' ', '"': '"', '/': '/',
  '\\': '\\', N: '', _: ' ', L: ' ', P: ' ',
};

function hexVal(ch) {
  if (ch >= '0' && ch <= '9') return ch.charCodeAt(0) - 48;
  if (ch >= 'a' && ch <= 'f') return ch.charCodeAt(0) - 87;
  if (ch >= 'A' && ch <= 'F') return ch.charCodeAt(0) - 55;
  return -1;
}

// ---------------------------------------------------------------------------

class Parser {
  constructor(text) {
    const { lines, endedWithBreak } = splitLines(text);
    this.lines = lines;
    this.endedWithBreak = endedWithBreak;
    this.pos = 0;
    this.anchors = new Map();
  }

  err(msg, row) {
    const r = row === undefined ? this.pos : row;
    return new Error('YAML parse error at line ' + (r + 1) + ': ' + msg);
  }

  skipTrivia(pos) {
    while (pos < this.lines.length) {
      const l = this.lines[pos];
      if (isBlank(l) || isComment(l)) { pos++; continue; }
      break;
    }
    return pos;
  }

  // ------------------------------------------------------------- document

  parseDocument() {
    let pos = this.skipTrivia(0);
    while (pos < this.lines.length && this.lines[pos][0] === '%') {
      pos = this.skipTrivia(pos + 1); // %YAML / %TAG directives
    }
    if (pos >= this.lines.length) return null;
    const line = this.lines[pos];
    if (isDocMarker(line, '...')) {
      this.pos = pos + 1;
      this.assertDocEnd();
      return null;
    }
    if (isDocMarker(line, '---')) {
      let rest = line.slice(3);
      let k = 0;
      while (k < rest.length && isSpaceTab(rest[k])) k++;
      rest = rest.slice(k);
      if (rest === '' || rest[0] === '#') {
        pos++;
      } else {
        // Inline content after '---' (e.g. '--- a: 1'); treat as column 0.
        this.lines[pos] = rest;
      }
    }
    this.pos = this.skipTrivia(pos);
    if (this.pos >= this.lines.length) return null;
    if (isDocMarker(this.lines[this.pos], '...')) {
      this.pos++;
      this.assertDocEnd();
      return null;
    }
    const value = this.parseBlockNode(0);
    this.pos = this.skipTrivia(this.pos);
    if (this.pos < this.lines.length) {
      if (isDocMarker(this.lines[this.pos], '...')) {
        this.pos++;
        this.assertDocEnd();
        return value;
      }
      throw this.err('expected a single document in the stream');
    }
    return value;
  }

  assertDocEnd() {
    let pos = this.skipTrivia(this.pos);
    while (pos < this.lines.length && this.lines[pos][0] === '%') {
      pos = this.skipTrivia(pos + 1);
    }
    if (pos < this.lines.length) {
      throw this.err('expected a single document in the stream', pos);
    }
    this.pos = pos;
  }

  // --------------------------------------------------------- block level

  // Parse a block node starting at this.pos (a non-blank, non-comment line
  // whose indent is >= minIndent). Node indent is taken from the line itself.
  parseBlockNode(minIndent) {
    const row = this.pos;
    const line = this.lines[row];
    const indent = indentOf(line);
    if (indent < minIndent) throw this.err('bad indentation', row);
    if (line[indent] === '\t') {
      throw this.err('tab characters cannot be used for indentation', row);
    }
    const content = line.slice(indent);
    if (isSeqEntry(content)) return this.parseBlockSeq(indent);
    if (this.scanMapKey(row, indent) !== null) return this.parseBlockMap(indent);
    const c0 = content[0];
    if (c0 === '|' || c0 === '>') {
      const header = this.parseScalarHeader(content, row);
      this.pos = row + 1;
      return this.parseBlockScalar(header, indent);
    }
    return this.parseInlineNode(row, indent, indent - 1);
  }

  // Parse the value of 'key:' / '-' when nothing follows on the same line.
  parseChildOrNull(parentIndent) {
    this.pos = this.skipTrivia(this.pos);
    if (this.pos >= this.lines.length) return null;
    const line = this.lines[this.pos];
    if (isDocMarker(line, '---') || isDocMarker(line, '...')) return null;
    const ind = indentOf(line);
    const content = line.slice(ind);
    // A block sequence may sit at the same indent as its parent mapping key.
    if (isSeqEntry(content) && ind >= parentIndent) return this.parseBlockNode(ind);
    if (ind > parentIndent) return this.parseBlockNode(ind);
    return null;
  }

  parseBlockSeq(indent) {
    const items = [];
    for (;;) {
      this.pos = this.skipTrivia(this.pos);
      if (this.pos >= this.lines.length) break;
      const row = this.pos;
      const line = this.lines[row];
      if (isDocMarker(line, '---') || isDocMarker(line, '...')) break;
      const ind = indentOf(line);
      if (ind < indent) break;
      if (ind > indent) throw this.err('bad indentation of a sequence entry', row);
      const content = line.slice(indent);
      if (!isSeqEntry(content)) break;
      let sp = 0;
      while (1 + sp < content.length && isSpaceTab(content[1 + sp])) sp++;
      const after = content.slice(1 + sp);
      if (after === '' || after[0] === '#') {
        this.pos = row + 1;
        items.push(this.parseChildOrNull(indent));
      } else {
        // Compact entry ('- key: val', '- - x', ...): rewrite the line so the
        // entry content becomes a virtual line at its own column, then parse.
        const col = indent + 1 + sp;
        this.lines[row] = ' '.repeat(col) + after;
        items.push(this.parseBlockNode(indent + 1));
      }
    }
    return items;
  }

  parseBlockMap(indent) {
    const obj = {};
    for (;;) {
      this.pos = this.skipTrivia(this.pos);
      if (this.pos >= this.lines.length) break;
      const row = this.pos;
      const line = this.lines[row];
      if (isDocMarker(line, '---') || isDocMarker(line, '...')) break;
      const ind = indentOf(line);
      if (ind < indent) break;
      if (ind > indent) throw this.err('bad indentation of a mapping entry', row);
      if (line[ind] === '\t') {
        throw this.err('tab characters cannot be used for indentation', row);
      }
      const key = this.scanMapKey(row, ind);
      if (key === null) throw this.err("could not find expected ':'", row);
      const cr = key.colonRow;
      const cline = this.lines[cr];
      let c = key.colonCol + 1;
      while (c < cline.length && isSpaceTab(cline[c])) c++;
      const rest = cline.slice(c);
      let value;
      if (rest === '' || rest[0] === '#') {
        this.pos = cr + 1;
        value = this.parseChildOrNull(indent);
      } else {
        value = this.parseInlineNode(cr, c, indent);
      }
      if (!key.quoted && key.keyRaw === '<<') {
        this.applyMerge(obj, value, row);
      } else {
        const keyStr = key.quoted ? key.keyValue : toKeyString(resolveScalar(key.keyRaw));
        obj[keyStr] = value;
      }
    }
    return obj;
  }

  applyMerge(obj, value, row) {
    const mergeOne = (m) => {
      if (m === null || typeof m !== 'object' || Array.isArray(m)) {
        throw this.err('invalid merge key value', row);
      }
      for (const k of Object.keys(m)) {
        if (!Object.prototype.hasOwnProperty.call(obj, k)) obj[k] = m[k];
      }
    };
    if (Array.isArray(value)) {
      for (const m of value) mergeOne(m);
    } else if (value !== null) {
      mergeOne(value);
    }
  }

  // Locate 'key:' in a (possibly quoted) mapping line. Returns null when the
  // line is not a mapping entry.
  scanMapKey(row, indent) {
    const line = this.lines[row];
    const c0 = line[indent];
    if (c0 === "'" || c0 === '"') {
      const q = this.parseQuoted(row, indent);
      const l2 = this.lines[q.row];
      let c = q.col;
      while (c < l2.length && isSpaceTab(l2[c])) c++;
      if (l2[c] !== ':') return null;
      if (c + 1 < l2.length && !isSpaceTab(l2[c + 1])) return null;
      return { quoted: true, keyValue: q.value, colonRow: q.row, colonCol: c };
    }
    if (c0 === '-' || c0 === '?' || isFlowIndicator(c0)) return null;
    let i = indent;
    while (i < line.length) {
      const ch = line[i];
      if (ch === ':') {
        if (i + 1 >= line.length || isSpaceTab(line[i + 1])) {
          const keyRaw = rtrim(line.slice(indent, i));
          if (keyRaw === '') return null;
          return { quoted: false, keyRaw, colonRow: row, colonCol: i };
        }
      } else if (ch === '#') {
        if (i > indent && isSpaceTab(line[i - 1])) return null;
      }
      i++;
    }
    return null;
  }

  // -------------------------------------------------------- inline values

  // Parse a value that starts mid-line: anchors/tags, block scalar header,
  // alias, flow collection, quoted scalar, or a (possibly multi-line) plain
  // scalar. Sets this.pos past the node and returns the value.
  parseInlineNode(row, col, parentIndent) {
    const line = this.lines[row];
    let c = col;
    while (c < line.length && isSpaceTab(line[c])) c++;
    let anchor = null;
    let forceStr = false;
    for (;;) {
      const ch = line[c];
      if (ch === '&') {
        const nm = this.readName(row, c + 1);
        anchor = nm.text;
        c = nm.end;
        while (c < line.length && isSpaceTab(line[c])) c++;
        continue;
      }
      if (ch === '!') {
        const tag = this.readTag(row, c);
        if (tag === '!!str' || tag === '!<tag:yaml.org,2002:str>') forceStr = true;
        // Other tags are ignored; resolution proceeds as for a plain node.
        c = tag.end;
        while (c < line.length && isSpaceTab(line[c])) c++;
        continue;
      }
      break;
    }
    if (c >= line.length || line[c] === '#') {
      this.pos = row + 1;
      let v = this.parseChildOrNull(parentIndent);
      if (v === null && forceStr) v = '';
      if (anchor !== null) this.anchors.set(anchor, v);
      return v;
    }
    const ch = line[c];
    let value;
    if (ch === '|' || ch === '>') {
      const header = this.parseScalarHeader(line.slice(c), row);
      this.pos = row + 1;
      value = this.parseBlockScalar(header, parentIndent);
    } else if (ch === '*') {
      const nm = this.readName(row, c + 1);
      let k = nm.end;
      while (k < line.length && isSpaceTab(line[k])) k++;
      if (k < line.length && line[k] !== '#') {
        throw this.err('unexpected characters after alias', row);
      }
      if (!this.anchors.has(nm.text)) throw this.err('found undefined alias', row);
      value = this.anchors.get(nm.text);
      this.pos = row + 1;
    } else if (ch === '{' || ch === '[') {
      const cur = { row, col: c };
      value = this.parseFlowValue(cur);
      const l2 = this.lines[cur.row];
      let k = cur.col;
      while (l2 !== undefined && k < l2.length && isSpaceTab(l2[k])) k++;
      if (l2 !== undefined && k < l2.length && l2[k] !== '#') {
        throw this.err('unexpected characters after flow collection', cur.row);
      }
      this.pos = cur.row + 1;
    } else if (ch === "'" || ch === '"') {
      const q = this.parseQuoted(row, c);
      const l2 = this.lines[q.row];
      let k = q.col;
      while (k < l2.length && isSpaceTab(l2[k])) k++;
      if (k < l2.length && l2[k] !== '#') {
        throw this.err('unexpected characters after quoted scalar', q.row);
      }
      value = q.value;
      this.pos = q.row + 1;
    } else if (ch === ']' || ch === '}' || ch === ',') {
      throw this.err('unexpected character ' + ch, row);
    } else {
      const raw = this.parsePlainMulti(row, c, parentIndent);
      value = forceStr ? raw : resolveScalar(raw);
    }
    if (anchor !== null) this.anchors.set(anchor, value);
    return value;
  }

  // Anchor/alias name: runs until whitespace or a flow indicator.
  readName(row, col) {
    const line = this.lines[row];
    let i = col;
    while (i < line.length && !isSpaceTab(line[i]) && !isFlowIndicator(line[i])) i++;
    if (i === col) throw this.err('expected an anchor/alias name', row);
    return { text: line.slice(col, i), end: i };
  }

  // Tag token starting at '!'. Returns the tag text and end column.
  readTag(row, col) {
    const line = this.lines[row];
    let i = col + 1;
    let verbatim = false;
    if (line[i] === '<') {
      verbatim = true;
      i++;
      while (i < line.length && line[i] !== '>') i++;
      if (i >= line.length) throw this.err('unterminated tag', row);
      return { tag: line.slice(col, i + 1), end: i + 1 };
    }
    while (i < line.length && !isSpaceTab(line[i]) && !isFlowIndicator(line[i])) i++;
    return { tag: line.slice(col, i), end: i };
  }

  // Multi-line plain scalar (block context). Returns the folded raw text.
  parsePlainMulti(row, col, parentIndent) {
    const first = this.lines[row];
    const parts = [];
    const firstText = cutComment(first.slice(col));
    this.checkPlainColon(firstText, row);
    parts.push(firstText);
    let lastRow = row;
    let j = row + 1;
    let blanks = 0;
    for (;;) {
      if (j >= this.lines.length) break;
      const l = this.lines[j];
      if (isDocMarker(l, '---') || isDocMarker(l, '...')) break;
      if (isComment(l)) { j++; continue; } // comment lines: skipped, no fold effect
      if (isBlank(l)) { blanks++; j++; continue; }
      const ind = indentOf(l);
      if (ind <= parentIndent) break;
      let k = ind;
      while (k < l.length && isSpaceTab(l[k])) k++;
      const t = cutComment(l.slice(k));
      this.checkPlainColon(t, j);
      parts.push(blanks > 0 ? '\n'.repeat(blanks) : ' ');
      parts.push(t);
      blanks = 0;
      lastRow = j;
      j++;
    }
    this.pos = lastRow + 1;
    return parts.join('');
  }

  // A ':' followed by space/EOL inside a plain scalar value is an error,
  // matching PyYAML's "mapping values are not allowed here".
  checkPlainColon(text, row) {
    for (let i = 0; i < text.length; i++) {
      if (text[i] === ':' && (i + 1 >= text.length || isSpaceTab(text[i + 1]))) {
        throw this.err('mapping values are not allowed here', row);
      }
    }
  }

  // -------------------------------------------------------- block scalars

  parseScalarHeader(content, row) {
    const style = content[0]; // '|' or '>'
    let chomping = null;
    let indentInd = 0;
    let i = 1;
    for (; i < content.length; i++) {
      const ch = content[i];
      if (ch === '+' || ch === '-') {
        if (chomping !== null) throw this.err('bad block scalar header', row);
        chomping = ch;
      } else if (ch >= '1' && ch <= '9') {
        if (indentInd !== 0) throw this.err('bad block scalar header', row);
        indentInd = ch.charCodeAt(0) - 48;
      } else {
        break;
      }
    }
    while (i < content.length && isSpaceTab(content[i])) i++;
    if (i < content.length && content[i] !== '#') {
      throw this.err('bad block scalar header', row);
    }
    return { style, chomping, indentInd };
  }

  // Consumes block scalar content lines starting at this.pos.
  parseBlockScalar(header, parentIndent) {
    let blockIndent;
    if (header.indentInd > 0) {
      blockIndent = parentIndent + header.indentInd;
    } else {
      blockIndent = parentIndent + 1;
      let k = this.pos;
      while (k < this.lines.length && isBlank(this.lines[k])) k++;
      if (k < this.lines.length) {
        const l = this.lines[k];
        if (!isDocMarker(l, '---') && !isDocMarker(l, '...')) {
          const ind = indentOf(l);
          if (ind > parentIndent) blockIndent = ind;
        }
      }
    }
    const rows = [];
    let j = this.pos;
    for (; j < this.lines.length; j++) {
      const l = this.lines[j];
      if (isDocMarker(l, '...') || isDocMarker(l, '---')) break;
      if (isBlank(l)) { rows.push(''); continue; }
      const ind = indentOf(l);
      if (ind < blockIndent) break;
      rows.push(l.slice(blockIndent));
    }
    this.pos = j;

    let lastNonEmpty = -1;
    for (let i = rows.length - 1; i >= 0; i--) {
      if (rows[i] !== '') { lastNonEmpty = i; break; }
    }
    const bodyRows = rows.slice(0, lastNonEmpty + 1);
    const body = header.style === '|' ? bodyRows.join('\n') : foldRows(bodyRows);

    let numBreaks;
    if (rows.length === 0) numBreaks = 0;
    else if (lastNonEmpty === -1) numBreaks = rows.length;
    else numBreaks = rows.length - lastNonEmpty;
    if (rows.length > 0 && j - 1 === this.lines.length - 1 && !this.endedWithBreak) {
      numBreaks--;
    }
    const full = body + '\n'.repeat(numBreaks);

    if (header.chomping === '-') {
      let end = full.length;
      while (end > 0 && full[end - 1] === '\n') end--;
      return full.slice(0, end);
    }
    if (header.chomping === '+') return full;
    if (body === '') return '';
    return body + '\n';
  }

  // ------------------------------------------------------ quoted scalars

  // Parse a single- or double-quoted scalar starting at (row, col).
  // Returns { value, row, col } with col just past the closing quote.
  parseQuoted(row, col) {
    const quote = this.lines[row][col];
    let buf = '';
    let r = row;
    let c = col + 1;
    let suppressFold = false;
    for (;;) {
      if (r >= this.lines.length) throw this.err('unterminated quoted scalar', row);
      const line = this.lines[r];
      while (c < line.length) {
        const ch = line[c];
        if (quote === "'") {
          if (ch === "'") {
            if (c + 1 < line.length && line[c + 1] === "'") {
              buf += "'";
              c += 2;
              continue;
            }
            return { value: buf, row: r, col: c + 1 };
          }
          buf += ch;
          c++;
        } else {
          if (ch === '"') return { value: buf, row: r, col: c + 1 };
          if (ch === '\\') {
            if (c + 1 >= line.length) {
              // Escaped line break: continuation without a folded space.
              suppressFold = true;
              c = line.length;
              break;
            }
            const esc = line[c + 1];
            if (esc === 'x' || esc === 'u' || esc === 'U') {
              const n = esc === 'x' ? 2 : esc === 'u' ? 4 : 8;
              if (c + 1 + n >= line.length + 1) {
                // ensure enough chars remain on this line
                if (c + 2 + n > line.length) throw this.err('bad escape sequence', r);
              }
              let cp = 0;
              for (let h = 0; h < n; h++) {
                const hv = hexVal(line[c + 2 + h]);
                if (hv < 0) throw this.err('bad escape sequence', r);
                cp = cp * 16 + hv;
              }
              buf += String.fromCodePoint(cp);
              c += 2 + n;
              continue;
            }
            const rep = Object.prototype.hasOwnProperty.call(DQ_ESCAPES, esc)
              ? DQ_ESCAPES[esc]
              : undefined;
            if (rep === undefined) throw this.err('unknown escape character', r);
            buf += rep;
            c += 2;
            continue;
          }
          buf += ch;
          c++;
        }
      }
      // End of line inside quotes: fold the line break.
      r++;
      let blanks = 0;
      while (r < this.lines.length && isBlank(this.lines[r])) { blanks++; r++; }
      if (r >= this.lines.length) throw this.err('unterminated quoted scalar', row);
      const nl = this.lines[r];
      let k = 0;
      while (k < nl.length && isSpaceTab(nl[k])) k++;
      c = k;
      if (suppressFold) {
        suppressFold = false;
      } else {
        buf += blanks > 0 ? '\n'.repeat(blanks) : ' ';
      }
    }
  }

  // ------------------------------------------------------- flow context

  flowSkip(cur) {
    for (;;) {
      const l = this.lines[cur.row];
      if (l === undefined) return;
      if (cur.col >= l.length) { cur.row++; cur.col = 0; continue; }
      const ch = l[cur.col];
      if (isSpaceTab(ch)) { cur.col++; continue; }
      if (ch === '#') { cur.col = l.length; continue; }
      return;
    }
  }

  flowPeek(cur) {
    const l = this.lines[cur.row];
    if (l === undefined || cur.col >= l.length) return '';
    return l[cur.col];
  }

  parseFlowValue(cur) {
    this.flowSkip(cur);
    const ch = this.flowPeek(cur);
    if (ch === '') throw this.err('unexpected end of input inside flow collection', cur.row);
    if (ch === '{') return this.parseFlowMap(cur);
    if (ch === '[') return this.parseFlowSeq(cur);
    if (ch === "'" || ch === '"') {
      const q = this.parseQuoted(cur.row, cur.col);
      cur.row = q.row;
      cur.col = q.col;
      return q.value;
    }
    if (ch === '&') {
      const line = this.lines[cur.row];
      const nm = this.readName(cur.row, cur.col + 1);
      cur.col = nm.end;
      const v = this.parseFlowValue(cur);
      this.anchors.set(nm.text, v);
      return v;
    }
    if (ch === '*') {
      const nm = this.readName(cur.row, cur.col + 1);
      cur.col = nm.end;
      if (!this.anchors.has(nm.text)) throw this.err('found undefined alias', cur.row);
      return this.anchors.get(nm.text);
    }
    if (ch === '|' || ch === '>') {
      throw this.err('block scalars are not allowed inside flow collections', cur.row);
    }
    const raw = this.parseFlowPlain(cur);
    return resolveScalar(raw);
  }

  // Flow plain scalar: runs across lines until a flow indicator, a ':'
  // followed by separation/indicator, or a ' #' comment.
  parseFlowPlain(cur) {
    const parts = [];
    for (;;) {
      const l = this.lines[cur.row];
      if (l === undefined) break;
      if (isDocMarker(l, '---') || isDocMarker(l, '...')) break;
      let i = cur.col;
      let seg = '';
      let hitComment = false;
      while (i < l.length) {
        const ch = l[i];
        if (isFlowIndicator(ch)) break;
        if (ch === ':') {
          const nx = i + 1 < l.length ? l[i + 1] : '';
          if (nx === '' || isSpaceTab(nx) || isFlowIndicator(nx)) break;
        }
        if (ch === '#' && (i === 0 || isSpaceTab(l[i - 1]))) {
          hitComment = true;
          break;
        }
        seg += ch;
        i++;
      }
      parts.push(rtrim(seg));
      if (!hitComment && i < l.length) { cur.col = i; break; } // stopped at indicator
      // reached EOL: the scalar may continue on the next line
      cur.row++;
      cur.col = 0;
      const nl = this.lines[cur.row];
      if (nl === undefined) break;
      if (isDocMarker(nl, '---') || isDocMarker(nl, '...')) break;
      let k = 0;
      while (k < nl.length && isSpaceTab(nl[k])) k++;
      cur.col = k;
      parts.push(' ');
    }
    // Trim trailing fold spaces.
    let out = parts.join('');
    return rtrim(out);
  }

  parseFlowKey(cur) {
    const ch = this.flowPeek(cur);
    if (ch === "'" || ch === '"') {
      const q = this.parseQuoted(cur.row, cur.col);
      cur.row = q.row;
      cur.col = q.col;
      return { quoted: true, value: q.value };
    }
    if (ch === '{' || ch === '[') {
      throw this.err('flow collections as mapping keys are not supported', cur.row);
    }
    return { quoted: false, value: this.parseFlowPlain(cur) };
  }

  parseFlowMap(cur) {
    cur.col++; // consume '{'
    const obj = {};
    this.flowSkip(cur);
    if (this.flowPeek(cur) === '}') { cur.col++; return obj; }
