      this.flowSkip(cur);
      let value = this.parseFlowValue(cur);
      this.flowSkip(cur);
      // Single-pair implicit mapping entry: '[a: 1]' -> [{a: 1}]
      if (this.flowPeek(cur) === ':') {
        cur.col++;
        this.flowSkip(cur);
        const nx = this.flowPeek(cur);
        let v2 = null;
        if (!(nx === ',' || nx === ']' || nx === '')) v2 = this.parseFlowValue(cur);
        const m = {};
        m[toKeyString(value)] = v2;
        value = m;
      }
      arr.push(value);
      this.flowSkip(cur);
      const ch = this.flowPeek(cur);
      if (ch === ',') {
        cur.col++;
        this.flowSkip(cur);
        if (this.flowPeek(cur) === ']') { cur.col++; return arr; }
        continue;
      }
      if (ch === ']') { cur.col++; return arr; }
      throw this.err("expected ',' or ']' in flow sequence", cur.row);
    }
  }
}

