// Test-only stub for resolveScalar (real one is written by another agent).
export function resolveScalar(s) {
  if (s === '' || s === '~' || s === 'null' || s === 'Null' || s === 'NULL') return null;
  if (s === 'true' || s === 'True' || s === 'TRUE') return true;
  if (s === 'false' || s === 'False' || s === 'FALSE') return false;
  // int
  let t = s;
  let neg = false;
  if (t[0] === '+' || t[0] === '-') { neg = t[0] === '-'; t = t.slice(1); }
  const digits = t.split('_').join('');
  if (/^[0-9]+$/.test(digits)) return (neg ? -1 : 1) * parseInt(digits, 10);
  if (/^0x[0-9a-fA-F]+$/.test(digits)) return (neg ? -1 : 1) * parseInt(digits.slice(2), 16);
  if (/^0o[0-7]+$/.test(digits)) return (neg ? -1 : 1) * parseInt(digits.slice(2), 8);
  // float
  const f = s.split('_').join('');
  if (/^[+-]?\.(inf|Inf|INF)$/.test(f)) return f[0] === '-' ? -Infinity : Infinity;
  if (/^\.(nan|NaN|NAN)$/.test(f)) return NaN;
  if (/^[+-]?([0-9]+\.[0-9]*|\.[0-9]+|[0-9]+)([eE][+-]?[0-9]+)?$/.test(f) && (f.indexOf('.') >= 0 || /[eE]/.test(f))) {
    return parseFloat(f);
  }
  return s;
}

