import { safeLoad } from './parser.mjs';
import { inspect, isDeepStrictEqual } from 'node:util';
import { execFileSync } from 'node:child_process';

const EXE = '/workspace/dataset/test9_executable';

function dump(input) {
  try {
    return { out: execFileSync(EXE, ['--a', input], { encoding: 'utf8' }), err: null };
  } catch (e) {
    return { out: null, err: e };
  }
}

function canon(v) {
  if (v === null) return 'null';
  if (typeof v === 'number') return Object.is(v, -0) ? '-0' : String(v);
  if (typeof v !== 'object') return inspect(v);
  if (Array.isArray(v)) return '[' + v.map(canon).join(', ') + ']';
  return '{' + Object.keys(v).map((k) => inspect(k) + ': ' + canon(v[k])).join(', ') + '}';
}

const cases = [
  // the four sample test cases
  '{name: Alice, age: 30, city: New York}',
  'a: 123\nb: -456\nc: 0',
  'metadata:\n  version: "1.0"\n  authors:\n    - Alice\n    - Bob\n    - Charlie\n  tags:\n    - python\n    - yaml\n    - test\ndata:\n  - id: 1\n    value: 100\n    active: true\n  - id: 2\n    value: 200\n    active: false\nconfig:\n  debug: false\n  log_level: INFO\n  max_retries: 3',
  'chomp: |\n  Line 1\n  Line 2\n',
  // block scalar variants
  'a: |-\n  Line 1\n  Line 2\n',
  'a: |+\n  Line 1\n  Line 2\n\n\n',
  'a: >\n  Line 1\n  Line 2\n\n  Line 3\n',
  'a: >-\n  fold\n  me\n',
  'a: |2\n   ind\n  base\n',
  'a: |\n  x',
  'a: |+\n  x',
  'a: >\n  next line\n    * bullet\n\n    * list\n  last\n',
  // flow
  "{'q key': {n: [1, {deep: true}], m: {}}, e: []}",
  '[a: 1, b: 2]',
  '[a: b, c]',
  '{x: 1, y}',
  '{a: {b: [1, [2, {c: null}]]}, d: "e"}',
  'just a flow-less scalar',
  '[1, two, 3.5, true, null, ~]',
  // quoted
  'a: "x\\ny\\t\\"q\\" \\\\ \\x41B"\nb: \'it\'\'s\'\nc: plain # comment\nd:\ne: ~\nf: null\ng: "dq # not comment"\n',
  "multi: 'single\n  quoted\n\n  lines'\ndq: \"double\n  quoted\"",
  // misc block
  'k:\n- 1\n- key: val\n  k2: v2\n- - nested\n  - seq\n',
  'plain multi\n  line folded\n  here\n',
  'a: &x 1\nb: *x\n',
  'base: &b\n  x: 1\n  y: 2\nderived:\n  <<: *b\n  y: 3\n',
  'c: !!str 5',
  '---\ndoc: 1\n',
  '--- 42\n',
  'empty',
  'null',
  '~',
  'a: 2020-01-01\nb: 1.5\nc: .inf\nd: 0x1F\n',
  'url: http://example.com/x?y=1\n',
  'seq at key level:\n- a\n- b\n',
  'deep:\n    very:\n        nested: ok\n',
  '"quoted key": v\n\'sq key\': w\n1: int key\ntrue: bool key\n',
  'a: "x"\nb: \'y\'\n',
  'list:\n  -\n  - \n',
];

// error cases: executable must fail AND we must throw
const errCases = [
  'key: val:',
  'a: 1\n  bad: indent\n',
  "'unterminated",
  '[1, 2',
  '{a: 1',
  'a: *missing\n',
  '---\na: 1\n...\nb: 2\n',
];

let fail = 0;

for (const input of cases) {
  const { out, err } = dump(input);
  if (err) {
    console.log('SKIP (exe failed):', inspect(input));
    continue;
  }
  let v1, v2, e1 = null, e2 = null;
  try { v1 = safeLoad(input); } catch (e) { e1 = e; }
  try { v2 = safeLoad(out); } catch (e) { e2 = e; }
  if (e1 || e2) {
    fail++;
    console.log('FAIL(parse):', inspect(input));
    if (e1) console.log('  input parse error:', e1.message);
    if (e2) console.log('  dump reparse error:', e2.message, '\n  dump was:\n' + out);
    continue;
  }
  if (!isDeepStrictEqual(v1, v2)) {
    fail++;
    console.log('FAIL(mismatch):', inspect(input));
    console.log('  v1:', canon(v1));
    console.log('  v2:', canon(v2));
    console.log('  dump:\n' + out);
  } else {
    console.log('ok:', inspect(input).slice(0, 60), '=>', canon(v1).slice(0, 90));
  }
}

for (const input of errCases) {
  const { err } = dump(input);
  let threw = false;
  try { safeLoad(input); } catch (e) { threw = true; }
  if (!err && !threw) { console.log('ok-err(both fine?):', inspect(input)); continue; }
  if (err && threw) { console.log('ok-err:', inspect(input).slice(0, 50)); continue; }
  fail++;
  console.log('FAIL(err-case):', inspect(input), 'exe failed:', !!err, 'we threw:', threw);
}

console.log(fail === 0 ? '\nALL PASS' : '\n' + fail + ' FAILURES');
process.exit(fail === 0 ? 0 : 1);

