// PyYAML-faithful YAML serializer.
// Reproduces `yaml.dump(value, explicit_start=True)` byte-for-byte for values
// built per the shared value spec (null / boolean / number / string / Array /
// plain object / Map).
//
// Extra conventions supported (all optional, plain values work without them):
//   - a boxed Number (`new Number(x)`) is always rendered as a YAML float,
//     so integral floats like 1.0 survive the JS int/float ambiguity;
//   - a BigInt is rendered as a YAML int with full precision;
//   - a Map is treated as a mapping with typed keys (numbers, booleans, null),
//     which plain JS objects cannot represent; plain objects use string keys.
//
// Calibrated against /workspace/dataset/test9_executable (PyYAML 5.x/6.x,
// default Dumper: default_flow_style=False, sort_keys=True, width=80,
// allow_unicode=False).

import { isPlainSafe } from './resolve.mjs';

const BEST_WIDTH = 80;
const BEST_INDENT = 2;

// ---------------------------------------------------------------------------
// Output writer tracking the current column (in Unicode code points, like
// PyYAML's len()-based column count) for width-80 folding decisions.
// ---------------------------------------------------------------------------
class Writer {
  constructor() {
    this.parts = [];
    this.col = 0;
  }
  w(s) {
    this.parts.push(s);
    let n = 0;
    for (const ch of s) void ch, n++;
    this.col += n;
  }
  nl() {
    this.parts.push('\n');
    this.col = 0;
  }
  pad(indent) {
    if (this.col < indent) {
      this.parts.push(' '.repeat(indent - this.col));
      this.col = indent;
    }
  }
  // PyYAML write_indent(): line break, then pad to indent.
  lineBreakPad(indent) {
    this.nl();
    this.pad(indent);
  }
  text() {
    return this.parts.join('');
  }
}

function codePointLen(s) {
  let n = 0;
  for (const ch of s) void ch, n++;
  return n;
}

// ---------------------------------------------------------------------------
// Scalar source text for non-string scalars.
// ---------------------------------------------------------------------------

// Python repr() of a double, reimplemented on top of JS shortest-round-trip
// Number#toString digits.
function pyFloatRepr(x) {
  if (Number.isNaN(x)) return '.nan';
  if (x === Infinity) return '.inf';
  if (x === -Infinity) return '-.inf';
  let s = pyDoubleRepr(x);
  // PyYAML SafeRepresenter.represent_float: repr without a '.' but with an
  // exponent is not a valid YAML 1.1 float, so ".0" is inserted before 'e'
  // (repr(1e16)='1e+16' -> '1.0e+16', repr(1e-05)='1e-05' -> '1.0e-05').
  if (s.indexOf('.') === -1 && s.indexOf('e') !== -1) {
    const i = s.indexOf('e');
    s = s.slice(0, i) + '.0' + s.slice(i);
  }
  return s;
}

// Exact Python repr() formatting for a finite double.
function pyDoubleRepr(x) {
  if (x === 0) return Object.is(x, -0) ? '-0.0' : '0.0';
  const neg = x < 0;
  const a = neg ? -x : x;
  const js = a.toString();
  let digits;
  let exp10; // value = d[0].d[1..] * 10^exp10
  const ePos = js.indexOf('e');
  if (ePos !== -1) {
    const mant = js.slice(0, ePos);
    const exp = parseInt(js.slice(ePos + 1), 10);
    const dot = mant.indexOf('.');
    if (dot === -1) {
      digits = mant;
      exp10 = exp + mant.length - 1;
    } else {
      digits = mant.slice(0, dot) + mant.slice(dot + 1);
      exp10 = exp + dot - 1;
    }
  } else {
    const dot = js.indexOf('.');
    if (dot === -1) {
      digits = js;
      exp10 = js.length - 1;
    } else {
      const intPart = js.slice(0, dot);
      const fracPart = js.slice(dot + 1);
      if (intPart !== '0') {
        digits = intPart + fracPart;
        exp10 = intPart.length - 1;
      } else {
        let zeros = 0;
        while (zeros < fracPart.length && fracPart[zeros] === '0') zeros++;
        digits = fracPart.slice(zeros);
        exp10 = -(zeros + 1);
      }
    }
  }
  // Trim trailing zeros from the digit string (JS may emit e.g. '10000000000000000'
  // for 1e16, where the shortest digits are just '1').
  let last = digits.length;
  while (last > 1 && digits[last - 1] === '0') last--;
  digits = digits.slice(0, last);

  const decpt = exp10 + 1; // position of decimal point relative to digits
  let out;
  if (decpt > -4 && decpt <= 16) {
    // fixed notation
    if (decpt <= 0) {
      out = '0.' + '0'.repeat(-decpt) + digits;
    } else if (decpt >= digits.length) {
      out = digits + '0'.repeat(decpt - digits.length) + '.0';
    } else {
      out = digits.slice(0, decpt) + '.' + digits.slice(decpt);
    }
  } else {
    // scientific notation, exponent at least two digits
    let m = digits[0];
    if (digits.length > 1) m += '.' + digits.slice(1);
    const ea = Math.abs(exp10);
    out = m + 'e' + (exp10 < 0 ? '-' : '+') + (ea < 10 ? '0' + ea : String(ea));
  }
  return neg ? '-' + out : out;
}

// Python str() of an int, for integer-valued JS Numbers.
function pyIntStr(x) {
  const a = Math.abs(x);
  if (a < 1e21) return String(x); // plain digits in this range
  // Beyond 1e21 JS switches to exponent notation; expand it to digits.
  // (Precision is already lost at this magnitude; best effort.)
  const s = a.toString();
  const ePos = s.indexOf('e');
  if (ePos === -1) return String(x);
  const mant = s.slice(0, ePos);
  const exp = parseInt(s.slice(ePos + 1), 10);
  const dot = mant.indexOf('.');
  const digits = dot === -1 ? mant : mant.slice(0, dot) + mant.slice(dot + 1);
  const intLen = dot === -1 ? mant.length : dot;
  const zeros = exp - (intLen - 1);
  const out = zeros >= 0
    ? digits + '0'.repeat(zeros)
    : digits.slice(0, intLen + exp); // not expected for integers
  return x < 0 ? '-' + out : out;
}

// Source text of a non-string scalar (what PyYAML's representer produces).
function scalarSourceText(value) {
  if (value === null || value === undefined) return 'null';
  if (typeof value === 'boolean') return value ? 'true' : 'false';
  if (typeof value === 'bigint') return value.toString();
  if (typeof value === 'number') {
    return Number.isInteger(value) ? pyIntStr(value) : pyFloatRepr(value);
  }
  if (value instanceof Number) return pyFloatRepr(value.valueOf());
  return String(value);
}

// ---------------------------------------------------------------------------
// Scalar style analysis (block context, allow_unicode=False).
// ---------------------------------------------------------------------------

// Whether a string can use single-quoted style. PyYAML disallows it when the
// scalar contains "special characters" (anything outside 0x20..0x7E except
// '\n', since allow_unicode=False) or a space adjacent to a line break.
function canSingleQuoted(text) {
  let prev = -1;
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp !== 0x0A && (cp < 0x20 || cp > 0x7E)) return false;
    if (cp === 0x20 && prev === 0x0A) return false; // break followed by space
    if (cp === 0x0A && prev === 0x20) return false; // space followed by break
    prev = cp;
  }
  return true;
}

// ---------------------------------------------------------------------------
// Scalar writers (ports of PyYAML's emitter write_plain / write_single_quoted
// / write_double_quoted, including width-80 folding).
// ---------------------------------------------------------------------------

function writePlain(wr, text, contIndent) {
  if (text.length === 0) return;
  const len = text.length;
  let start = 0;
  let end = 0;
  let spaces = false;
  while (end <= len) {
    const ch = end < len ? text[end] : null;
    if (spaces) {
      if (ch !== ' ') {
        if (start + 1 === end && wr.col > BEST_WIDTH) {
          wr.lineBreakPad(contIndent);
        } else {
          wr.w(text.slice(start, end));
        }
        start = end;
      }
    } else if (ch === null || ch === ' ') {
      wr.w(text.slice(start, end));
      start = end;
    }
    spaces = ch === ' ';
    end++;
  }
}

function writeSingleQuoted(wr, text, contIndent) {
  wr.w("'");
  const len = text.length;
  let start = 0;
  let end = 0;
  let spaces = false;
  let breaks = false;
  while (end <= len) {
    const ch = end < len ? text[end] : null;
    if (spaces) {
      if (ch !== ' ') {
        if (start + 1 === end && wr.col > BEST_WIDTH && start !== 0 && end !== len) {
          wr.lineBreakPad(contIndent);
        } else {
          wr.w(text.slice(start, end));
        }
        start = end;
      }
    } else if (breaks) {
      if (ch !== '\n') {
        // A run of k newlines is emitted as k+1 bare line breaks followed by
        // padding to the continuation indent (PyYAML write_line_break() for
        // each break plus one, then write_indent() which only pads here).
        const k = end - start;
        for (let i = 0; i <= k; i++) wr.nl();
        wr.pad(contIndent);
        start = end;
      }
    } else if (ch === null || ch === ' ' || ch === '\n' || ch === "'") {
      wr.w(text.slice(start, end));
      start = end;
    }
    if (ch === "'") {
      wr.w("''");
      start = end + 1;
    }
    spaces = ch === ' ';
    breaks = ch === '\n';
    end++;
  }
  wr.w("'");
}

const DQ_ESCAPES = {
  '': '\\0',
  '\x07': '\\a',
  '\x08': '\\b',
  '\x09': '\\t',
  '\x0A': '\\n',
  '\x0B': '\\v',
  '\x0C': '\\f',
  '\x0D': '\\r',
  '\x1B': '\\e',
  '"': '\\"',
  '\\': '\\\\',
  '\x85': '\\N',
  '\xA0': '\\_',
  ' ': '\\L',
  ' ': '\\P',
};

function dqEscape(cp) {
  const hex = cp.toString(16).toUpperCase();
  if (cp <= 0xFF) return '\\x' + (cp <= 0xF ? '0' + hex : hex);
  if (cp <= 0xFFFF) return '\\u' + '0'.repeat(4 - hex.length) + hex;
  return '\\U' + '0'.repeat(8 - hex.length) + hex;
}

function writeDoubleQuoted(wr, text, contIndent) {
  wr.w('"');
  const len = text.length;
  let start = 0;
  let end = 0;
  while (end <= len) {
    const ch = end < len ? text[end] : null;
    let esc = null;
    let adv = 1;
    if (ch !== null) {
      const cp0 = ch.codePointAt(0);
      if (Object.prototype.hasOwnProperty.call(DQ_ESCAPES, ch)) {
        esc = DQ_ESCAPES[ch];
      } else if (cp0 < 0x20 || cp0 > 0x7E) {
        let cp = cp0;
        if (cp0 >= 0xD800 && cp0 <= 0xDBFF && end + 1 < len) {
          const lo = text.charCodeAt(end + 1);
          if (lo >= 0xDC00 && lo <= 0xDFFF) {
            cp = (cp0 - 0xD800) * 0x400 + (lo - 0xDC00) + 0x10000;
            adv = 2;
          }
        }
        esc = dqEscape(cp);
      }
    }
    if (ch === null || esc !== null) {
      if (start < end) {
        wr.w(text.slice(start, end));
        start = end;
      }
      if (esc !== null) {
        wr.w(esc);
        start = end + adv;
      }
    } else if (end > 0 && end < len - 1 && (ch === ' ' || start >= end) &&
               wr.col + (end - start) > BEST_WIDTH) {
      // Fold: pending text + backslash, line break, indent, then a backslash
      // if the fold happened at a space (the space itself stays pending).
      wr.w(text.slice(start, end));
      wr.w('\\');
      wr.lineBreakPad(contIndent);
      start = end;
      if (text[start] === ' ') wr.w('\\');
    }
    end += esc !== null && adv === 2 ? 2 : 1;
  }
  wr.w('"');
}

// Writes any scalar value; returns the style used ('plain' | 'single' | 'double').
function writeScalar(wr, value, contIndent) {
  if (typeof value === 'string') {
    if (isPlainSafe(value)) {
      writePlain(wr, value, contIndent);
      return 'plain';
    }
    if (canSingleQuoted(value)) {
      writeSingleQuoted(wr, value, contIndent);
      return 'single';
    }
    writeDoubleQuoted(wr, value, contIndent);
    return 'double';
  }
  writePlain(wr, scalarSourceText(value), contIndent);
  return 'plain';
}

// ---------------------------------------------------------------------------
// Value classification.
// ---------------------------------------------------------------------------

function isMapLike(v) {
  return v instanceof Map || (v !== null && typeof v === 'object' &&
    !Array.isArray(v) && !(v instanceof Number));
}

function isCollection(v) {
  return Array.isArray(v) || isMapLike(v);
}

function isEmptyCollection(v) {
  if (Array.isArray(v)) return v.length === 0;
  if (v instanceof Map) return v.size === 0;
  return Object.keys(v).length === 0;
}

function mapEntries(v) {
  if (v instanceof Map) return Array.from(v.entries());
  return Object.keys(v).map((k) => [k, v[k]]);
}

// ---------------------------------------------------------------------------
// Key sorting: PyYAML applies Python's sorted() to mapping items and silently
// keeps insertion order when keys are not mutually comparable (mixed types).
// ---------------------------------------------------------------------------

function keyClass(k) {
  if (typeof k === 'string') return 'str';
  if (k === null || k === undefined) return 'null';
  return 'num'; // number, boolean, bigint, boxed Number: mutually comparable in Python
}

function numKey(k) {
  if (typeof k === 'boolean') return k ? 1 : 0;
  if (typeof k === 'bigint') return k; // BigInt vs Number comparison below
  if (k instanceof Number) return k.valueOf();
  return k;
}

function cmpNumericKeys(a, b) {
  const ka = numKey(a);
  const kb = numKey(b);
  if (typeof ka === 'bigint' || typeof kb === 'bigint') {
    const ba = typeof ka === 'bigint' ? ka : BigInt(ka);
    const bb = typeof kb === 'bigint' ? kb : BigInt(kb);
    return ba < bb ? -1 : ba > bb ? 1 : 0;
  }
  return ka < kb ? -1 : ka > kb ? 1 : 0;
}

// Code point order (Python string comparison), not UTF-16 unit order.
function cmpCodePoints(a, b) {
  const ai = Array.from(a);
  const bi = Array.from(b);
  const n = Math.min(ai.length, bi.length);
  for (let i = 0; i < n; i++) {
    const ca = ai[i].codePointAt(0);
    const cb = bi[i].codePointAt(0);
    if (ca !== cb) return ca - cb;
  }
  return ai.length - bi.length;
}

function sortedEntries(mapLike) {
  const entries = mapEntries(mapLike);
  if (entries.length < 2) return entries;
  let cls = null;
  for (const [k] of entries) {
    const c = keyClass(k);
    if (cls === null) cls = c;
    else if (c !== cls) return entries; // TypeError in Python -> insertion order
  }
  const sorted = entries.slice();
  if (cls === 'str') sorted.sort((a, b) => cmpCodePoints(a[0], b[0]));
  else if (cls === 'num') sorted.sort((a, b) => cmpNumericKeys(a[0], b[0]));
  return sorted;
}

// ---------------------------------------------------------------------------
// Key analysis: PyYAML uses a simple key (`k: v`) only for non-empty,
// single-line scalars shorter than 128 chars; anything else gets the
// explicit `? key` / `: value` form.
// ---------------------------------------------------------------------------

function keySourceText(k) {
  return typeof k === 'string' ? k : scalarSourceText(k);
}

function isSimpleKey(k) {
  const text = keySourceText(k);
  if (text.length === 0) return false;
  if (text.indexOf('\n') !== -1) return false;
  return codePointLen(text) < 128;
}

// ---------------------------------------------------------------------------
// Block structure emission.
// ---------------------------------------------------------------------------

function writeKeyScalar(wr, k, contIndent) {
  writeScalar(wr, k, contIndent);
}

// Value part after `key:` (the colon is already written).
function writeMapValue(wr, value, mapIndent) {
  if (!isCollection(value)) {
    wr.w(' ');
    writeScalar(wr, value, mapIndent + BEST_INDENT);
  } else if (isEmptyCollection(value)) {
    wr.w(' ');
    wr.w(Array.isArray(value) ? '[]' : '{}');
  } else if (Array.isArray(value)) {
    emitSeq(wr, value, mapIndent, false); // indentless sequence
  } else {
    emitMap(wr, value, mapIndent + BEST_INDENT, false);
  }
}

function writeKeyValue(wr, k, v, indent) {
  if (isSimpleKey(k)) {
    writeKeyScalar(wr, k, indent);
    wr.w(':');
    writeMapValue(wr, v, indent);
  } else {
    wr.w('? ');
    writeKeyScalar(wr, k, indent + BEST_INDENT);
    wr.nl();
    wr.pad(indent);
    wr.w(':');
    writeMapValue(wr, v, indent);
  }
}

function emitMap(wr, mapLike, indent, inlineFirst) {
  const entries = sortedEntries(mapLike);
  entries.forEach(([k, v], idx) => {
    if (!(idx === 0 && inlineFirst)) {
      wr.nl();
      wr.pad(indent);
    }
    writeKeyValue(wr, k, v, indent);
  });
}

// Value part after a sequence dash (the dash is already written).
function writeSeqItem(wr, item, seqIndent) {
  wr.w(' ');
  if (!isCollection(item)) {
    writeScalar(wr, item, seqIndent + BEST_INDENT);
  } else if (isEmptyCollection(item)) {
    wr.w(Array.isArray(item) ? '[]' : '{}');
  } else if (Array.isArray(item)) {
    emitSeq(wr, item, seqIndent + BEST_INDENT, true);
  } else {
    emitMap(wr, item, seqIndent + BEST_INDENT, true);
  }
}

function emitSeq(wr, arr, indent, inlineFirst) {
  arr.forEach((item, idx) => {
    if (idx === 0 && inlineFirst) {
      wr.w('-');
    } else {
      wr.nl();
      wr.pad(indent);
      wr.w('-');
    }
    writeSeqItem(wr, item, indent);
  });
}

// ---------------------------------------------------------------------------
// Public entry point.
// ---------------------------------------------------------------------------

// Returns exactly what yaml.dump(value, explicit_start=True) produces,
// including the single trailing newline.
export function dumpDocument(value) {
  const wr = new Writer();
  if (isCollection(value)) {
    if (isEmptyCollection(value)) {
      wr.w(Array.isArray(value) ? '--- []' : '--- {}');
      wr.nl();
    } else {
      wr.w('---');
      if (Array.isArray(value)) emitSeq(wr, value, 0, false);
      else emitMap(wr, value, 0, false);
      wr.nl();
    }
  } else {
    wr.w('--- ');
    const style = writeScalar(wr, value, BEST_INDENT);
    wr.nl();
    // A plain scalar in root context leaves the document "open ended", so
    // PyYAML closes it with an explicit document-end marker.
    if (style === 'plain') wr.w('...\n');
  }
  return wr.text();
}

